window.XP_SOUND_ASSETS={"ballon": "data:audio/mpeg;base64,", "chimes": "data:audio/mpeg;base64,", "chord": "data:audio/mpeg;base64,", "critical": "data:audio/mpeg;base64,", "ding": "data:audio/mpeg;base64,", "error": "data:audio/mpeg;base64,", "load": "data:audio/mpeg;base64,", "notify": "data:audio/mpeg;base64,", "shutdown": "data:audio/mpeg;base64,", "startup": "data:audio/mpeg;base64,", "tada": "data:audio/mpeg;base64,"};
window.XPSounds = (() => {
  const context=new (window.AudioContext||window.webkitAudioContext)({latencyHint:'interactive'});
  const output=context.createDynamicsCompressor();output.threshold.value=-22;output.knee.value=12;output.ratio.value=4;output.attack.value=.005;output.release.value=.16;output.connect(context.destination);
  const buffers=new Map(), active=new Set(),events=[],pending=new Map();
  let muted=false;
  const ready=Promise.all(Object.entries(XP_SOUND_ASSETS).sort(([a],[b])=>(a==='startup'?-1:0)-(b==='startup'?-1:0)).map(async([name,url])=>{
    const bytes=Uint8Array.from(atob(url.split(',')[1]),c=>c.charCodeAt(0));
    const buffer=await context.decodeAudioData(bytes.buffer);
    let onset=buffer.length;
    for(let c=0;c<buffer.numberOfChannels;c++) {const data=buffer.getChannelData(c);for(let i=0;i<onset;i++)if(Math.abs(data[i])>.003){onset=i;break;}}
    let sum=0,count=0,peak=0;for(let c=0;c<buffer.numberOfChannels;c++){const data=buffer.getChannelData(c);for(let i=onset;i<data.length;i++){const v=Math.abs(data[i]);peak=Math.max(peak,v);if(v>.008){sum+=v*v;count++;}}}
    const level=Math.min(.045/Math.max(.001,Math.sqrt(sum/Math.max(1,count))),.35/Math.max(.001,peak));
    buffers.set(name,{buffer,level,offset:Math.max(0,onset/buffer.sampleRate-.004)});flush();
  })).then(flush);
  function flush(){if(context.state!=='running'||muted)return;for(const [name] of [...pending]){if(!buffers.has(name))continue;pending.delete(name);start(name);}}
  function start(name){const item=buffers.get(name);if(!item){pending.set(name,true);return;}
    if(active.size>=8){const old=active.values().next().value;old.stop();active.delete(old);}
    const source=context.createBufferSource(),gain=context.createGain();source.buffer=item.buffer;gain.gain.value=item.level;source.connect(gain);gain.connect(output);active.add(source);source.onended=()=>{active.delete(source);source.disconnect();gain.disconnect();};source.start(0,item.offset);
    events.push({name,time:performance.now(),offset:item.offset});if(events.length>32)events.shift();
  }
  function play(name){if(muted||!XP_SOUND_ASSETS[name])return;pending.set(name,true);if(context.state==='running')flush();else context.resume().then(flush).catch(()=>{});}
  context.addEventListener('statechange',flush);
  const unlock=()=>{context.resume().then(flush).catch(()=>{});};
  document.addEventListener('pointerdown',unlock,{capture:true});document.addEventListener('keydown',unlock,{capture:true});
  return {play,ready,context,output,setMuted(value){muted=value;if(value){pending.clear();for(const source of active)source.stop();active.clear();}},get events(){return events.map(e=>({...e}));},get prepared(){return buffers.size;}};
})();

